/* Volta Studio — Styles */
@import url('https://fonts.googleapis.com/css2?family=Playfair+Display:wght@400;700;900&family=Inter:wght@300;400;500&display=swap');

*, *::before, *::after {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

:root {
  --bg: #F5F2ED;
  --text: #1A1A1A;
  --accent: #C4957A;
  --accent2: #8A9E8C;
  --accent3: #D4C5A9;
  --font-serif: 'Playfair Display', Georgia, serif;
  --font-sans: 'Inter', system-ui, sans-serif;
}

html {
  scroll-behavior: smooth;
}

body {
  background: var(--bg);
  color: var(--text);
  font-family: var(--font-sans);
  font-size: 16px;
  line-height: 1.6;
  overflow-x: hidden;
}

/* Header / Nav */
.site-header {
  position: fixed;
  top: 0;
  left: 0;
  right: 0;
  z-index: 100;
  padding: 24px 48px;
  display: flex;
  align-items: center;
  justify-content: space-between;
  background: var(--bg);
}

.logo {
  font-family: var(--font-serif);
  font-weight: 700;
  font-size: 1.25rem;
  text-decoration: none;
  color: var(--text);
  letter-spacing: -0.02em;
}

.logo:hover {
  opacity: 0.7;
}

.desktop-nav {
  display: flex;
  gap: 40px;
  list-style: none;
}

.desktop-nav a {
  font-family: var(--font-sans);
  font-size: 0.875rem;
  font-weight: 400;
  text-decoration: none;
  color: var(--text);
  letter-spacing: 0.04em;
  text-transform: uppercase;
  transition: opacity 0.2s;
}

.desktop-nav a:hover {
  opacity: 0.5;
}

/* Hamburger */
.hamburger {
  display: none;
  flex-direction: column;
  gap: 6px;
  cursor: pointer;
  background: none;
  border: none;
  padding: 4px;
  z-index: 200;
}

.hamburger span {
  display: block;
  width: 28px;
  height: 1.5px;
  background: var(--text);
  transition: transform 0.3s, opacity 0.3s;
}

.hamburger.active span:nth-child(1) {
  transform: translateY(7.5px) rotate(45deg);
}

.hamburger.active span:nth-child(2) {
  opacity: 0;
}

.hamburger.active span:nth-child(3) {
  transform: translateY(-7.5px) rotate(-45deg);
}

/* Mobile Menu Overlay */
.mobile-menu {
  position: fixed;
  inset: 0;
  background: var(--bg);
  z-index: 150;
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  gap: 48px;
  opacity: 0;
  pointer-events: none;
  transition: opacity 0.4s ease;
}

.mobile-menu.active {
  opacity: 1;
  pointer-events: all;
}

.mobile-menu a {
  font-family: var(--font-serif);
  font-size: 2.5rem;
  font-weight: 700;
  text-decoration: none;
  color: var(--text);
  letter-spacing: -0.02em;
  transition: opacity 0.2s;
}

.mobile-menu a:hover {
  opacity: 0.5;
}

/* Page Sections */
.page-content {
  padding-top: 100px;
}

.container {
  max-width: 1400px;
  margin: 0 auto;
  padding: 0 48px;
}

/* Hero */
.hero {
  padding: 120px 48px 80px;
  max-width: 1200px;
}

.hero h1 {
  font-family: var(--font-serif);
  font-size: clamp(2.5rem, 6vw, 5rem);
  font-weight: 900;
  line-height: 1.1;
  letter-spacing: -0.03em;
}

/* Media Showcase */
.media-showcase {
  padding: 0 48px 80px;
}

.media-grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 16px;
  max-width: 1400px;
  margin: 0 auto;
}

.media-block {
  aspect-ratio: 4/3;
  display: block;
}

.media-block:nth-child(1) { background: #C4957A; }
.media-block:nth-child(2) { background: #8A9E8C; }
.media-block:nth-child(3) { background: #D4C5A9; }

/* Client Marquee */
.client-marquee {
  padding: 80px 0;
  overflow: hidden;
  border-top: 1px solid rgba(26,26,26,0.1);
  border-bottom: 1px solid rgba(26,26,26,0.1);
}

.marquee-row {
  display: flex;
  overflow: hidden;
  margin-bottom: 24px;
}

.marquee-row:last-child {
  margin-bottom: 0;
}

.marquee-track {
  display: flex;
  gap: 0;
  white-space: nowrap;
  will-change: transform;
}

.marquee-row:nth-child(odd) .marquee-track {
  animation: marquee-left 30s linear infinite;
}

.marquee-row:nth-child(even) .marquee-track {
  animation: marquee-right 30s linear infinite;
}

@keyframes marquee-left {
  from { transform: translateX(0); }
  to { transform: translateX(-50%); }
}

@keyframes marquee-right {
  from { transform: translateX(-50%); }
  to { transform: translateX(0); }
}

.marquee-item {
  font-family: var(--font-serif);
  font-size: 1.5rem;
  font-weight: 700;
  padding: 0 32px;
  color: var(--text);
  opacity: 0.8;
}

.marquee-separator {
  color: var(--accent);
  opacity: 0.6;
}

/* About */
.about-section {
  padding: 120px 48px;
  max-width: 900px;
  margin: 0 auto;
}

.about-section h2 {
  font-family: var(--font-sans);
  font-size: 0.75rem;
  font-weight: 500;
  letter-spacing: 0.15em;
  text-transform: uppercase;
  margin-bottom: 32px;
  opacity: 0.6;
}

.about-section p {
  font-family: var(--font-sans);
  font-size: 1.125rem;
  line-height: 1.8;
  font-weight: 300;
  margin-bottom: 24px;
}

/* Founder Letter */
.founder-letter {
  padding: 160px 48px 120px;
  max-width: 720px;
  margin: 0 auto;
}

.founder-letter .eyebrow {
  font-family: var(--font-sans);
  font-size: 0.75rem;
  font-weight: 500;
  letter-spacing: 0.15em;
  text-transform: uppercase;
  margin-bottom: 48px;
  opacity: 0.6;
}

.founder-letter h1 {
  font-family: var(--font-serif);
  font-size: clamp(2rem, 4vw, 3.25rem);
  font-weight: 900;
  line-height: 1.2;
  letter-spacing: -0.02em;
  margin-bottom: 56px;
}

.letter-body {
  font-family: var(--font-sans);
  font-size: 1.125rem;
  line-height: 1.9;
  font-weight: 300;
}

.letter-body p {
  margin-bottom: 28px;
}

.letter-body p:last-child {
  margin-bottom: 0;
}

/* Services */
.services-hero {
  padding: 160px 48px 80px;
  max-width: 900px;
}

.services-hero h1 {
  font-family: var(--font-serif);
  font-size: clamp(2rem, 4vw, 3.5rem);
  font-weight: 900;
  line-height: 1.15;
  letter-spacing: -0.02em;
  margin-bottom: 32px;
}

.services-hero .subtitle {
  font-family: var(--font-serif);
  font-size: 1.5rem;
  font-weight: 400;
  font-style: italic;
  opacity: 0.7;
}

.divider {
  max-width: 900px;
  margin: 0 auto 80px;
  padding: 0 48px;
}

.divider hr {
  border: none;
  border-top: 1px solid rgba(26,26,26,0.15);
}

.service-details {
  padding: 0 48px 120px;
  max-width: 900px;
  margin: 0 auto;
}

.service-details h2 {
  font-family: var(--font-serif);
  font-size: clamp(1.5rem, 3vw, 2rem);
  font-weight: 700;
  margin-bottom: 48px;
  letter-spacing: -0.01em;
}

.service-block {
  margin-bottom: 64px;
}

.service-block h3 {
  font-family: var(--font-serif);
  font-size: 1.75rem;
  font-weight: 700;
  margin-bottom: 20px;
  letter-spacing: -0.01em;
}

.service-block p {
  font-family: var(--font-sans);
  font-size: 1.0625rem;
  line-height: 1.8;
  font-weight: 300;
  opacity: 0.85;
}

/* Clients */
.clients-page {
  padding-top: 160px;
}

.clients-heading {
  padding: 0 48px 64px;
}

.clients-heading h1 {
  font-family: var(--font-serif);
  font-size: clamp(2rem, 4vw, 3.5rem);
  font-weight: 900;
  letter-spacing: -0.02em;
}

.clients-heading p {
  font-family: var(--font-serif);
  font-size: 1.25rem;
  font-style: italic;
  opacity: 0.6;
  margin-top: 12px;
}

.clients-grid-section {
  padding: 0 48px 120px;
}

.clients-grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 48px 48px;
  max-width: 1200px;
  margin: 0 auto;
}

.client-card h3 {
  font-family: var(--font-serif);
  font-size: 1.5rem;
  font-weight: 700;
  margin-bottom: 12px;
  letter-spacing: -0.01em;
}

.client-card p {
  font-family: var(--font-sans);
  font-size: 0.9375rem;
  line-height: 1.7;
  font-weight: 300;
  opacity: 0.8;
}

/* Contact */
.contact-page {
  min-height: 100vh;
  display: flex;
  flex-direction: column;
  justify-content: center;
  padding: 0 48px;
}

.contact-hero h1 {
  font-family: var(--font-serif);
  font-size: clamp(4rem, 15vw, 14rem);
  font-weight: 900;
  line-height: 0.9;
  letter-spacing: -0.04em;
  margin-bottom: 80px;
}

.contact-links {
  display: flex;
  gap: 48px;
  margin-top: auto;
  padding-bottom: 80px;
}

.contact-links a {
  font-family: var(--font-sans);
  font-size: 1rem;
  font-weight: 400;
  text-decoration: none;
  color: var(--text);
  letter-spacing: 0.04em;
  transition: opacity 0.2s;
  opacity: 0.7;
}

.contact-links a:hover {
  opacity: 1;
}

/* Mobile Responsive */
@media (max-width: 768px) {
  .site-header {
    padding: 20px 24px;
  }

  .desktop-nav {
    display: none;
  }

  .hamburger {
    display: flex;
  }

  .hero {
    padding: 120px 24px 60px;
  }

  .hero h1 {
    font-size: 2.25rem;
  }

  .media-showcase {
    padding: 0 24px 60px;
  }

  .media-grid {
    grid-template-columns: 1fr;
    gap: 12px;
  }

  .media-block {
    aspect-ratio: 16/9;
  }

  .client-marquee {
    padding: 60px 0;
  }

  .marquee-item {
    font-size: 1.125rem;
    padding: 0 20px;
  }

  .about-section {
    padding: 80px 24px;
  }

  .about-section p {
    font-size: 1rem;
  }

  .founder-letter {
    padding: 120px 24px 80px;
  }

  .founder-letter h1 {
    font-size: 1.875rem;
    margin-bottom: 40px;
  }

  .letter-body {
    font-size: 1rem;
  }

  .services-hero {
    padding: 120px 24px 60px;
  }

  .services-hero h1 {
    font-size: 1.875rem;
  }

  .divider {
    padding: 0 24px;
    margin-bottom: 60px;
  }

  .service-details {
    padding: 0 24px 80px;
  }

  .clients-page {
    padding-top: 120px;
  }

  .clients-heading {
    padding: 0 24px 48px;
  }

  .clients-grid-section {
    padding: 0 24px 80px;
  }

  .clients-grid {
    grid-template-columns: 1fr;
    gap: 40px;
  }

  .contact-page {
    padding: 0 24px;
  }

  .contact-hero h1 {
    font-size: 4rem;
    margin-bottom: 60px;
  }

  .contact-links {
    flex-direction: column;
    gap: 24px;
    padding-bottom: 60px;
  }
}

@media (max-width: 480px) {
  .contact-hero h1 {
    font-size: 3rem;
  }
}

