/* Volta Studio — Styles */
@import url('https://fonts.googleapis.com/css2?family=Playfair+Display:wght@400;700;900&family=Inter:wght@300;400;500&display=swap');

*, *::before, *::after {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

:root {
  --bg: #F5F2ED;
  --text: #1A1A1A;
  --accent: #C4957A;
  --accent2: #8A9E8C;
  --accent3: #D4C5A9;
  --font-serif: 'Playfair Display', Georgia, serif;
  --font-sans: 'Inter', system-ui, sans-serif;
}

html {
  scroll-behavior: smooth;
}

body {
  background: var(--bg);
  color: var(--text);
  font-family: var(--font-sans);
  font-size: 16px;
  line-height: 1.6;
  overflow-x: hidden;
}

/* Header / Nav */
.site-header {
  position: fixed;
  top: 0;
  left: 0;
  right: 0;
  z-index: 100;
  padding: 24px 48px;
  display: flex;
  align-items: center;
  justify-content: space-between;
  background: var(--bg);
}

.logo {
  font-family: var(--font-serif);
  font-weight: 700;
  font-size: 1.25rem;
  text-decoration: none;
  color: var(--text);
  letter-spacing: -0.02em;
}

.logo:hover {
  opacity: 0.7;
}

.desktop-nav {
  display: flex;
  gap: 40px;
  list-style: none;
}

.desktop-nav a {
  font-family: var(--font-sans);
  font-size: 0.875rem;
  font-weight: 400;
  text-decoration: none;
  color: var(--text);
  letter-spacing: 0.04em;
  text-transform: uppercase;
  transition: opacity 0.2s;
}

.desktop-nav a:hover {
  opacity: 0.5;
}

/* Hamburger */
.hamburger {
  display: none;
  flex-direction: column;
  gap: 6px;
  cursor: pointer;
  background: none;
  border: none;
  padding: 4px;
  z-index: 200;
}

.hamburger span {
  display: block;
  width: 28px;
  height: 1.5px;
  background: var(--text);
  transition: transform 0.3s, opacity 0.3s;
}

.hamburger.active span:nth-child(1) {
  transform: translateY(7.5px) rotate(45deg);
}

.hamburger.active span:nth-child(2) {
  opacity: 0;
}

.hamburger.active span:nth-child(3) {
  transform: translateY(-7.5px) rotate(-45deg);
}

/* Mobile Menu Overlay */
.mobile-menu {
  position: fixed;
  inset: 0;
  background: var(--bg);
  z-index: 150;
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  gap: 48px;
  opacity: 0;
  pointer-events: none;
  transition: opacity 0.4s ease;
}

.mobile-menu.active {
  opacity: 1;
  pointer-events: all;
}

.mobile-menu a {
  font-family: var(--font-serif);
  font-size: 2.5rem;
  font-weight: 700;
  text-decoration: none;
  color: var(--text);
  letter-spacing: -0.02em;
  transition: opacity 0.2s;
}

.mobile-menu a:hover {
  opacity: 0.5;
}

/* Page Sections */
.page-content {
  padding-top: 100px;
}

.container {
  max-width: 1400px;
  margin: 0 auto;
  padding: 0 48px;
}

/* Hero */
.hero {
  padding: 120px 48px 80px;
  max-width: 1200px;
}

.hero h1 {
  font-family: var(--font-serif);
  font-size: clamp(2.5rem, 6vw, 5rem);
  font-weight: 900;
  line-height: 1.1;
  letter-spacing: -0.03em;
}

/* Media Showcase */
.media-showcase {
  padding: 0 48px 80px;
}

.media-grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 16px;
  max-width: 1400px;
  margin: 0 auto;
}

.media-block {
  aspect-ratio: 4/3;
  display: block;
}

.media-block:nth-child(1) { background: #C4957A; }
.media-block:nth-child(2) { background: #8A9E8C; }
.media-block:nth-child(3) { background: #D4C5A9; }

/* Client Marquee */
.client-marquee {
  padding: 80px 0;
  overflow: hidden;
  border-top: 1px solid rgba(26,26,26,0.1);
  border-bottom: 1px solid rgba(26,26,26,0.1);
}

.marquee-row {
  display: flex;
  overflow: hidden;
  margin-bottom: 24px;
}

.marquee-row:last-child {
  margin-bottom: 0;
}

.marquee-track {
  display: flex;
  gap: 0;
  white-space: nowrap;
  will-change: transform;
}

.marquee-row:nth-child(odd) .marquee-track {
  animation: marquee-left 30s linear infinite;
}

.marquee-row:nth-child(even) .marquee-track {
  animation: marquee-right 30s linear infinite;
}

@keyframes marquee-left {
  from { transform: translateX(0); }
  to { transform: translateX(-50%); }
}

@keyframes marquee-right {
  from { transform: translateX(-50%); }
  to { transform: translateX(0); }
}

.marquee-item {
  font-family: var(--font-serif);
  font-size: 1.5rem;
  font-weight: 700;
  padding: 0 32px;
  color: var(--text);
  opacity: 0.8;
}

.marquee-separator {
  color: var(--accent);
  opacity: 0.6;
}

/* About */
